def seed_existing_expense_requisitions(apps, schema_editor):
    Expense = apps.get_model("webroaster", "Expense")
    alias = schema_editor.connection.alias
    for expense in Expense.objects.using(alias).all():
        if expense.expense_code is None:
            year = expense.expense_date.year if expense.expense_date else 2026
            expense.expense_code = f"EXP-{year}-{expense.pk:05d}"
        if expense.requisition_title in (None, "Expense Requisition"):
            expense.requisition_title = f"{expense.category} Expense {expense.pk}"
        if expense.requested_amount == 0:
            expense.requested_amount = expense.amount
        if expense.amount > 0 and expense.accountability_status == "not_due":
            expense.accountability_status = "submitted"
        expense.save(using=alias, update_fields=["expense_code", "requisition_title", "requested_amount", "accountability_status"])


